//! Files gitroute owns outside its config: the generated gitconfig, one
//! identity file per account, and a marked block at the end of the user's
//! global gitconfig that includes the generated file. See docs/NOTES.md for
//! the experiments behind the layout.

use std::env;
use std::fs;
use std::io;
use std::path::{Path, PathBuf};

use anyhow::{Context, Result, bail};

use crate::config::{Account, Config};
use crate::token_store::unix_now;

pub const BLOCK_START: &str = "# >>> gitroute (managed, do not edit)";
pub const BLOCK_END: &str = "# <<< gitroute";
const BLOCK: &str = "# >>> gitroute (managed, do not edit)\n[include]\n\tpath = ~/.config/gitroute/gitconfig\n# <<< gitroute\n";
const HEADER: &str =
    "# Generated by gitroute, do not edit: it's rewritten whenever accounts or rules change.\n";

/// `~/.config/gitroute`
pub fn managed_dir(home: &Path) -> PathBuf {
    home.join(".config/gitroute")
}

pub fn gitconfig_path(home: &Path) -> PathBuf {
    managed_dir(home).join("gitconfig")
}

pub fn identity_path(home: &Path, account_id: u64) -> PathBuf {
    managed_dir(home).join(format!("identities/{account_id}.gitconfig"))
}

/// The file git reads as global config: `$GIT_CONFIG_GLOBAL`, else `~/.gitconfig`.
pub fn global_gitconfig(home: &Path) -> PathBuf {
    match env::var_os("GIT_CONFIG_GLOBAL") {
        Some(path) if !path.is_empty() => path.into(),
        _ => home.join(".gitconfig"),
    }
}

/// `git-credential-gitroute`, installed next to the running binary.
pub fn helper_next_to_current_exe() -> Result<PathBuf> {
    let exe = env::current_exe().context("can't locate the running binary")?;
    let helper = exe.with_file_name("git-credential-gitroute");
    if !helper.is_file() {
        bail!(
            "{} not found; it's installed next to gitroute",
            helper.display()
        );
    }
    Ok(helper)
}

/// The helper the generated gitconfig should point at: the one recorded at
/// install if it still exists, otherwise the one next to this binary.
pub fn helper_for(config: &Config) -> Result<PathBuf> {
    match &config.helper_path {
        Some(path) if path.is_file() => Ok(path.clone()),
        _ => helper_next_to_current_exe(),
    }
}

/// The helper the generated gitconfig actually points git at, read back from
/// the file (it may predate `helper_path` being recorded).
pub fn current_helper(home: &Path) -> Option<PathBuf> {
    let text = fs::read_to_string(gitconfig_path(home)).ok()?;
    let value = text
        .lines()
        .filter_map(|l| l.trim().strip_prefix("helper ="))
        .map(str::trim)
        .rfind(|v| !v.is_empty())?;
    let value = value
        .strip_prefix('"')
        .and_then(|v| v.strip_suffix('"'))
        .map_or(value.to_string(), |v| {
            v.replace("\\\"", "\"").replace("\\\\", "\\")
        });
    let path = match value.strip_prefix("!'").and_then(|v| v.strip_suffix('\'')) {
        Some(quoted) => quoted.replace(r"'\''", "'"),
        None => value,
    };
    Some(PathBuf::from(path))
}

pub fn render_gitconfig(config: &Config, home: &Path, helper: &Path) -> String {
    let mut out = String::from(HEADER);
    if let Some(account) = config.default_account() {
        out += &format!("\n[user]\n{}", user_lines(account));
    }
    out += &format!(
        "\n[credential \"https://github.com\"]\n\
         \t# Empty first: drops helpers set earlier for github.com, such as Apple's osxkeychain.\n\
         \thelper =\n\
         \thelper = {}\n",
        quote(&helper_command(helper))
    );

    // Rules are sorted parent before child. git keeps the last value it
    // reads, so deeper rules must come later to win.
    let mut rules: Vec<_> = config.rules.iter().collect();
    rules.sort_by_key(|r| crate::paths::key(&r.path));
    for rule in rules {
        let Some(account_id) = rule.account.or(config.default_account_id) else {
            continue; // "use default" with no default: nothing to include
        };
        out += &format!(
            "\n[includeIf {}]\n\tpath = {}\n",
            quote(&format!(
                "gitdir/i:{}/",
                escape_glob(&rule.path.display().to_string())
            )),
            quote(&identity_path(home, account_id).display().to_string())
        );
    }
    out
}

pub fn render_identity(account: &Account) -> String {
    format!("{HEADER}[user]\n{}", user_lines(account))
}

fn user_lines(account: &Account) -> String {
    format!(
        "\tname = {}\n\temail = {}\n",
        quote(&account.commit_name),
        quote(&account.commit_email)
    )
}

/// Writes the generated gitconfig and identity files, and removes identity
/// files for accounts that no longer exist.
pub fn write_files(config: &Config, home: &Path, helper: &Path) -> Result<()> {
    let identities = managed_dir(home).join("identities");
    fs::create_dir_all(&identities)
        .with_context(|| format!("creating {}", identities.display()))?;
    for account in &config.accounts {
        write_atomic(&identity_path(home, account.id), &render_identity(account))?;
    }
    for entry in fs::read_dir(&identities)? {
        let path = entry?.path();
        let known = path
            .file_stem()
            .and_then(|s| s.to_str()?.parse::<u64>().ok())
            .is_some_and(|id| config.account(id).is_some());
        if !known && path.extension().is_some_and(|e| e == "gitconfig") {
            fs::remove_file(&path).with_context(|| format!("removing {}", path.display()))?;
        }
    }
    write_atomic(
        &gitconfig_path(home),
        &render_gitconfig(config, home, helper),
    )
}

/// True if `global` (see `global_gitconfig`) contains gitroute's block.
pub fn is_installed(global: &Path) -> Result<bool> {
    Ok(read_or_empty(global)?.lines().any(|l| l == BLOCK_START))
}

/// A planned change to the global gitconfig.
#[derive(Debug)]
pub struct Change {
    pub path: PathBuf,
    pub before: String,
    pub after: String,
}

impl Change {
    pub fn is_noop(&self) -> bool {
        self.before == self.after
    }

    pub fn diff(&self) -> String {
        let name = self.path.display().to_string();
        similar::TextDiff::from_lines(&self.before, &self.after)
            .unified_diff()
            .header(&name, &name)
            .to_string()
    }

    /// Backs up the current file (if any) to `~/.config/gitroute/backups/`,
    /// then writes the new content. Writes through a symlinked gitconfig
    /// (dotfiles setups) rather than replacing the link. Returns the backup.
    pub fn apply(&self, home: &Path) -> Result<Option<PathBuf>> {
        let target = match fs::canonicalize(&self.path) {
            Ok(real) => real,
            Err(e) if e.kind() == io::ErrorKind::NotFound => self.path.clone(),
            Err(e) => return Err(e).with_context(|| format!("resolving {}", self.path.display())),
        };
        let backup = if target.exists() {
            let dir = managed_dir(home).join("backups");
            fs::create_dir_all(&dir).with_context(|| format!("creating {}", dir.display()))?;
            let backup = dir.join(format!("gitconfig-{}", utc_stamp(unix_now())));
            fs::copy(&target, &backup).with_context(|| {
                format!("backing up {} to {}", target.display(), backup.display())
            })?;
            Some(backup)
        } else {
            None
        };
        write_atomic(&target, &self.after)?;
        Ok(backup)
    }
}

/// Adds gitroute's block at the end of `global`, moving it there if it's
/// elsewhere.
pub fn plan_install(global: &Path) -> Result<Change> {
    let path = global.to_path_buf();
    let before = read_or_empty(&path)?;
    let mut after = without_block(&before)?;
    if !after.is_empty() && !after.ends_with('\n') {
        after.push('\n');
    }
    after += BLOCK;
    Ok(Change {
        path,
        before,
        after,
    })
}

pub fn plan_uninstall(global: &Path) -> Result<Change> {
    let path = global.to_path_buf();
    let before = read_or_empty(&path)?;
    let after = without_block(&before)?;
    Ok(Change {
        path,
        before,
        after,
    })
}

/// `text` with gitroute's block removed. Everything else is left untouched.
fn without_block(text: &str) -> Result<String> {
    let mut out = String::with_capacity(text.len());
    let mut inside = false;
    for line in text.split_inclusive('\n') {
        match line.trim_end_matches(['\n', '\r']) {
            BLOCK_START if !inside => inside = true,
            BLOCK_END if inside => inside = false,
            _ if !inside => out.push_str(line),
            _ => {}
        }
    }
    if inside {
        bail!(
            "gitroute's block in the gitconfig has a start marker but no end marker; fix it by hand"
        );
    }
    Ok(out)
}

fn read_or_empty(path: &Path) -> Result<String> {
    match fs::read_to_string(path) {
        Ok(text) => Ok(text),
        Err(e) if e.kind() == io::ErrorKind::NotFound => Ok(String::new()),
        Err(e) => Err(e).with_context(|| format!("reading {}", path.display())),
    }
}

fn write_atomic(path: &Path, text: &str) -> Result<()> {
    let dir = path.parent().context("path has no parent")?;
    fs::create_dir_all(dir).with_context(|| format!("creating {}", dir.display()))?;
    let tmp = dir.join(format!(
        ".{}.gitroute-tmp",
        path.file_name().unwrap_or_default().to_string_lossy()
    ));
    fs::write(&tmp, text).with_context(|| format!("writing {}", tmp.display()))?;
    // Keep the original file's permissions.
    if let Ok(meta) = fs::metadata(path) {
        fs::set_permissions(&tmp, meta.permissions())?;
    }
    fs::rename(&tmp, path).with_context(|| format!("writing {}", path.display()))
}

/// A gitconfig value or subsection name in double quotes.
fn quote(s: &str) -> String {
    let escaped = s
        .replace('\\', "\\\\")
        .replace('"', "\\\"")
        .replace(['\n', '\r'], " ");
    format!("\"{escaped}\"")
}

/// `includeIf "gitdir:..."` patterns are wildmatch globs; escape the
/// metacharacters so a folder named `a[1]` matches literally.
fn escape_glob(path: &str) -> String {
    let mut out = String::with_capacity(path.len());
    for c in path.chars() {
        if matches!(c, '*' | '?' | '[' | '\\') {
            out.push('\\');
        }
        out.push(c);
    }
    out
}

/// What goes in `credential.helper`. git runs an absolute path through the
/// shell, so a path with spaces or other shell characters needs the `!`
/// form with single quotes.
fn helper_command(helper: &Path) -> String {
    let path = helper.display().to_string();
    let plain = path
        .chars()
        .all(|c| c.is_ascii_alphanumeric() || "/._-+".contains(c));
    if plain {
        path
    } else {
        format!("!'{}'", path.replace('\'', r"'\''"))
    }
}

/// `20261025T104512Z`
fn utc_stamp(unix: u64) -> String {
    let (days, secs) = (unix / 86_400, unix % 86_400);
    // Civil-from-days (Howard Hinnant's algorithm).
    let z = days as i64 + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z.rem_euclid(146_097);
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let day = doy - (153 * mp + 2) / 5 + 1;
    let month = if mp < 10 { mp + 3 } else { mp - 9 };
    let year = yoe + era * 400 + i64::from(month <= 2);
    format!(
        "{year:04}{month:02}{day:02}T{:02}{:02}{:02}Z",
        secs / 3600,
        secs / 60 % 60,
        secs % 60
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    fn account(id: u64, login: &str, name: &str, email: &str) -> Account {
        Account {
            id,
            login: login.into(),
            host: "github.com".into(),
            avatar_url: String::new(),
            commit_name: name.into(),
            commit_email: email.into(),
            emails: Vec::new(),
            needs_relogin: false,
        }
    }

    fn config() -> Config {
        let mut config = Config {
            default_account_id: Some(1),
            accounts: vec![
                account(1, "personal", "Aman Kumar Verma", "p@example.com"),
                account(2, "work", "Aman", "w@example.com"),
            ],
            ..Config::default()
        };
        config.set_rule("/c/work/oss".into(), None);
        config.set_rule("/c/work".into(), Some(2));
        config
    }

    #[test]
    fn renders_default_user_reset_helper_and_ordered_rules() {
        let home = Path::new("/h");
        let text = render_gitconfig(&config(), home, Path::new("/bin/git-credential-gitroute"));
        assert_eq!(
            text,
            format!(
                "{HEADER}\n\
                 [user]\n\tname = \"Aman Kumar Verma\"\n\temail = \"p@example.com\"\n\
                 \n[credential \"https://github.com\"]\n\
                 \t# Empty first: drops helpers set earlier for github.com, such as Apple's osxkeychain.\n\
                 \thelper =\n\thelper = \"/bin/git-credential-gitroute\"\n\
                 \n[includeIf \"gitdir/i:/c/work/\"]\n\tpath = \"/h/.config/gitroute/identities/2.gitconfig\"\n\
                 \n[includeIf \"gitdir/i:/c/work/oss/\"]\n\tpath = \"/h/.config/gitroute/identities/1.gitconfig\"\n"
            )
        );
    }

    #[test]
    fn no_default_skips_user_and_use_default_rules() {
        let mut c = config();
        c.default_account_id = None;
        let text = render_gitconfig(&c, Path::new("/h"), Path::new("/b/h"));
        assert!(!text.contains("[user]"));
        assert!(text.contains("gitdir/i:/c/work/\""));
        assert!(!text.contains("oss"));
    }

    #[test]
    fn quotes_values_globs_and_helper_paths() {
        assert_eq!(quote(r#"Al "Q" \x"#), r#""Al \"Q\" \\x""#);
        // `]` only means something after `[`, so escaping `[` is enough.
        assert_eq!(escape_glob("/a/b[1]/*?"), r"/a/b\[1]/\*\?");
        assert_eq!(
            helper_command(Path::new("/Users/a/.cargo/bin/git-credential-gitroute")),
            "/Users/a/.cargo/bin/git-credential-gitroute"
        );
        assert_eq!(
            helper_command(Path::new("/Applications/My Apps/it's/helper")),
            r"!'/Applications/My Apps/it'\''s/helper'"
        );
    }

    #[test]
    fn block_is_added_at_the_end_and_removed_cleanly() {
        let original = "[user]\n\tname = me\n[includeIf \"gitdir/i:~/x/\"]\n\tpath = ~/.x\n";
        let installed = format!("{original}{BLOCK}");
        assert_eq!(without_block(&installed).unwrap(), original);

        // Moved to the end if it's somewhere else; no trailing newline handled.
        let middle = format!("[a]\n{BLOCK}[b]\n\tx = 1");
        assert_eq!(without_block(&middle).unwrap(), "[a]\n[b]\n\tx = 1");
        assert!(without_block("[a]\n# >>> gitroute (managed, do not edit)\n[b]\n").is_err());
    }

    #[test]
    fn install_and_uninstall_round_trip_with_backup() {
        let tmp = tempfile::tempdir().unwrap();
        let home = tmp.path();
        let gitconfig = home.join(".gitconfig");
        fs::write(&gitconfig, "[user]\n\tname = me").unwrap();

        let install = plan_install(&gitconfig).unwrap();
        assert!(
            install
                .diff()
                .contains("+# >>> gitroute (managed, do not edit)")
        );
        let backup = install.apply(home).unwrap().unwrap();
        assert_eq!(fs::read_to_string(&backup).unwrap(), "[user]\n\tname = me");
        assert_eq!(
            fs::read_to_string(&gitconfig).unwrap(),
            format!("[user]\n\tname = me\n{BLOCK}")
        );
        assert!(is_installed(&gitconfig).unwrap());
        assert!(plan_install(&gitconfig).unwrap().is_noop());

        plan_uninstall(&gitconfig).unwrap().apply(home).unwrap();
        assert_eq!(
            fs::read_to_string(&gitconfig).unwrap(),
            "[user]\n\tname = me\n"
        );
        assert!(!is_installed(&gitconfig).unwrap());
        assert!(plan_uninstall(&gitconfig).unwrap().is_noop());
    }

    #[test]
    fn writes_through_a_symlinked_gitconfig() {
        let tmp = tempfile::tempdir().unwrap();
        let home = tmp.path();
        let dotfiles = home.join("dotfiles/gitconfig");
        fs::create_dir_all(dotfiles.parent().unwrap()).unwrap();
        fs::write(&dotfiles, "[core]\n").unwrap();
        std::os::unix::fs::symlink(&dotfiles, home.join(".gitconfig")).unwrap();

        let change = Change {
            path: home.join(".gitconfig"),
            before: "[core]\n".into(),
            after: format!("[core]\n{BLOCK}"),
        };
        change.apply(home).unwrap();
        assert!(
            fs::symlink_metadata(home.join(".gitconfig"))
                .unwrap()
                .is_symlink()
        );
        assert_eq!(fs::read_to_string(&dotfiles).unwrap(), change.after);
    }

    #[test]
    fn identity_files_follow_accounts() {
        let tmp = tempfile::tempdir().unwrap();
        let home = tmp.path();
        let mut c = config();
        write_files(&c, home, Path::new("/b/h")).unwrap();
        assert_eq!(
            fs::read_to_string(identity_path(home, 2)).unwrap(),
            format!("{HEADER}[user]\n\tname = \"Aman\"\n\temail = \"w@example.com\"\n")
        );
        c.accounts.retain(|a| a.id != 2);
        write_files(&c, home, Path::new("/b/h")).unwrap();
        assert!(!identity_path(home, 2).exists());
        assert!(identity_path(home, 1).exists());
    }

    #[test]
    fn current_helper_reads_back_what_was_written() {
        let tmp = tempfile::tempdir().unwrap();
        let home = tmp.path();
        assert_eq!(current_helper(home), None);
        for helper in [
            "/Users/a/.cargo/bin/git-credential-gitroute",
            "/Applications/My Apps/it's/git-credential-gitroute",
        ] {
            write_files(&config(), home, Path::new(helper)).unwrap();
            assert_eq!(current_helper(home), Some(PathBuf::from(helper)));
        }
    }

    #[test]
    fn utc_stamps() {
        assert_eq!(utc_stamp(0), "19700101T000000Z");
        assert_eq!(utc_stamp(1_793_014_712), "20261026T113832Z");
        assert_eq!(utc_stamp(951_782_400), "20000229T000000Z");
    }
}
